public class ListNode {
    int val;
    ListNode next;
    ListNode() {}
    ListNode(int val) { this.val = val; }
    ListNode(int val, ListNode next) { this.val = val; this.next = next; }
}

public void printList(ListNode head) {
    ListNode cur = head;
    while (cur != null) {
        System.out.println(cur.val);
        cur = cur.next;
    }
}

